DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (5162, 5164, 5165, 5166, 5171, 5172, 5175, 5176, 5177, 5178, 5179, 5181, 5182, 5183, 5184, 5187, 5188, 5189, 5191, 5192, 5193, 5194, 5195, 5196, 5198, 5199, 5200, 5201, 5204, 5205, 5206, 5207, 5210, 5211, 5212, 5213, 5214, 5215, 5216, 5217, 5218, 5219, 5220, 5221, 5222, 5223, 5224, 5226, 5227, 5228)) <> 50 THEN RAISE EXCEPTION 'expected 50 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (5162, 5164, 5165, 5166, 5171, 5172, 5175, 5176, 5177, 5178, 5179, 5181, 5182, 5183, 5184, 5187, 5188, 5189, 5191, 5192, 5193, 5194, 5195, 5196, 5198, 5199, 5200, 5201, 5204, 5205, 5206, 5207, 5210, 5211, 5212, 5213, 5214, 5215, 5216, 5217, 5218, 5219, 5220, 5221, 5222, 5223, 5224, 5226, 5227, 5228) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 496 THEN RAISE EXCEPTION 'expected 496 MPs with a timeline before'; END IF;
  IF (SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 6281 THEN RAISE EXCEPTION 'expected 6281 entries before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, background_timeline IS NOT NULL AS had, md5(coalesce(background_timeline::text, '')) AS th
  FROM public.mp_biography b;

UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-11-07'
  FROM bt_new n WHERE b.member_id = n.member_id AND b.background_timeline IS NULL;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  existing_changed integer;
  matching integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5162, 5164, 5165, 5166, 5171, 5172, 5175, 5176, 5177, 5178, 5179, 5181, 5182, 5183, 5184, 5187, 5188, 5189, 5191, 5192, 5193, 5194, 5195, 5196, 5198, 5199, 5200, 5201, 5204, 5205, 5206, 5207, 5210, 5211, 5212, 5213, 5214, 5215, 5216, 5217, 5218, 5219, 5220, 5221, 5222, 5223, 5224, 5226, 5227, 5228) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO existing_changed FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE o.had AND md5(coalesce(b.background_timeline::text, '')) IS DISTINCT FROM o.th;
  SELECT count(*) INTO matching FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-11-07';
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 50 %, existing timelines changed %, rows matching the file %, MPs with a timeline %, entries %',
    changed, changed_outside, existing_changed, matching, with_timeline, entry_total;
  IF changed <> 50 THEN RAISE EXCEPTION 'expected exactly 50 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 50 changed', changed_outside; END IF;
  IF existing_changed <> 0 THEN RAISE EXCEPTION '% of the 496 existing timelines changed', existing_changed; END IF;
  IF matching <> 50 THEN RAISE EXCEPTION 'expected 50 rows matching the file, got %', matching; END IF;
  IF with_timeline <> 546 THEN RAISE EXCEPTION 'expected 546 MPs with a timeline after, got %', with_timeline; END IF;
  IF entry_total <> 6656 THEN RAISE EXCEPTION 'expected 6656 entries, got %', entry_total; END IF;
END $$;

COMMIT;
